(()=>{'use strict';
const A=RepoAccount,U=RepoAdminUI,slot=document.querySelector('#x-collection-settings');let epoch=0,settings=null,scanPending=false;
async function load(){if(!A.user?.admin)return;const token=++epoch;
try{const data=await A.request('/api/editorial?action=x-settings');if(token!==epoch||!A.user?.admin)return;settings=data.settings;
slot.innerHTML=`<form id="x-collection-form"><label class="publish-control"><input id="x-collection-enabled" type="checkbox" ${settings.enabled?'checked':''}> Enable X.com scanning</label><p class="small">Searches run daily at 06:17 UTC. Enabling takes effect at the next scheduled run. Disabling prevents further searches; checks of saved candidates can continue.</p><p class="small">Scans use available free or purchased X API credits. Set your spending limit and auto-recharge preferences in the X Developer Console. The collector keeps a $2 balance reserve and reads at most 50 posts per run.</p><button class="button" type="submit">Save X.com scanning</button>${settings.enabled?` <button class="button outline" id="x-scan-now" type="button" ${scanPending?'disabled':''}>Scan now</button>`:''}<p id="x-collection-message" role="status"></p></form><p class="small"><a href="https://github.com/sparx1981/reposhelf-x-collector/actions/workflows/collect.yml" target="_blank" rel="noopener">View scan history and results ↗</a>. Manual searches also require this toggle to be enabled.</p>`;
const scanButton=document.querySelector('#x-scan-now');if(scanButton)scanButton.onclick=async()=>{if(scanPending||!A.user?.admin)return;scanPending=true;scanButton.disabled=true;const message=document.querySelector('#x-collection-message');message.textContent='Requesting an X scan…';try{const result=await A.request('/api/editorial?action=x-scan',{method:'POST',body:'{}'});if(token!==epoch||!A.user?.admin)return;message.textContent=result.reason;scanPending=result.requested===true||Boolean(result.activeRunId);}catch(error){if(token!==epoch||!A.user?.admin)return;message.textContent=error.message;scanPending=error.code==='x_dispatch_unconfirmed';}finally{scanButton.disabled=scanPending;}};
document.querySelector('#x-collection-form').onsubmit=async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button'),message=form.querySelector('[role="status"]'),enabled=form.querySelector('input').checked;button.disabled=true;message.textContent='Saving…';
try{await A.request('/api/editorial?action=x-settings',{method:'POST',body:JSON.stringify({revision:settings.revision,enabled})});if(token!==epoch||!A.user?.admin)return;await load();const current=document.querySelector('#x-collection-message');if(current)current.textContent=enabled?'Saved. Scanning is enabled for the next scheduled run.':'Saved. New X searches are disabled.';}
catch(error){if(token!==epoch||!A.user?.admin)return;message.textContent=error.message;if(error.status===409)void load();}finally{button.disabled=false;}};
}catch(error){if(token!==epoch||!A.user?.admin)return;slot.innerHTML=error.code==='migration_required'?'<p>Apply <a href="https://github.com/sparx1981/RepoShelf/blob/main/supabase/migrations/202610080027_x_collection_settings.sql" target="_blank" rel="noopener">migration 27</a> to use the scanning toggle. X searches stay disabled until setup is complete.</p>':U.errorHtml(error.message,'x-collection');}}
document.addEventListener('click',event=>{if(event.target.closest('[data-admin-tab="sync"], [data-retry="x-collection"]'))void load();});
window.addEventListener('reposhelf-account',()=>{epoch++;settings=null;scanPending=false;if(!A.user?.admin)slot.innerHTML='';else if(!new URL(location.href).searchParams.get('tab')||new URL(location.href).searchParams.get('tab')==='sync')void load();});
if(A.user?.admin&&(!new URL(location.href).searchParams.get('tab')||new URL(location.href).searchParams.get('tab')==='sync'))void load();
})();
